def change(file,old,new):
 s=file.read_text()
 if s.count(old)!=1: raise SystemExit(f"Marker mismatch in {file}: {old[:65]} (found {s.count(old)})")
 file.write_text(s.replace(old,new,1));print("Updated",file)
